      }
      setState(() => _engine = engine);
      // Restart tiles ONLY when their own app changed afterwards (see
      // [_restartIfAppChanged]) — record the signature the new engine
      // booted from.
      _appSignature = await _readAppSignature();
      final refreshSeconds = widget.app.tileWidget?.refreshSeconds;
      if (refreshSeconds != null) {
        _refreshTimer = Timer.periodic(Duration(seconds: refreshSeconds), (_) {
          _fireTileRefresh(engine);
        });
      }
    } on Object catch (error) {
      if (mounted) setState(() => _startError = error);
    }
  }

  /// The theme bridge for the tile's engine (issue #169) — same contract
  /// as the fullscreen app view: every apply prompts the user.
  FaThemeBridge? _themeBridge() {
    final store = ThemePackScope.maybeOf(context);
    final controller = FahThemeScope.maybeOf(context);
    if (store == null || controller == null) return null;
    return FaThemeBridgeHost(
      store: store,
      controller: controller,
      prompt: (pack) async {
        if (!mounted) return false;
        return showThemePackConsent(
          context,
          appName: widget.app.name,
          pack: pack,
        );
      },
    );
  }

  @override
  Widget build(BuildContext context) {
    final colors = FahColors.of(context);
    return Semantics(
      label: widget.app.name,
      button: true,
      child: Container(
        decoration: BoxDecoration(
          color: colors.panelAlt,
          borderRadius: BorderRadius.circular(16),
          border: Border.all(color: colors.border),
        ),
        child: ClipRRect(
          borderRadius: BorderRadius.circular(16),
          child: _buildBody(Theme.of(context)),
        ),
      ),
    );
  }

  Widget _buildBody(ThemeData theme) {
    final error = _startError;
    if (error != null) {
      // The tile entry failed to boot (missing file, JS error) — fall back
      // to the app icon so the cell never goes blank.
      return Center(
        child: AppIcon(app: widget.app, env: widget.env, size: 32),
      );
    }
    final engine = _engine;
    if (engine == null) {
      return const Center(
        child: SizedBox(
          width: 18,
          height: 18,
          child: CircularProgressIndicator(strokeWidth: 2),
        ),
      );
    }
    // Issue #1336: an engine that booted but never rendered must not spin
    // forever — same fallback as a failed boot: the app icon.
    return ValueListenableBuilder<Object?>(
      valueListenable: engine.bootError,
      builder: (context, bootError, _) {
        if (bootError != null) {
          return Center(
            child: AppIcon(app: widget.app, env: widget.env, size: 32),
          );
        }
        return ValueListenableBuilder<Map<String, dynamic>?>(
          valueListenable: engine.tree,
          builder: (context, tree, _) {
            if (tree == null) {
              return const Center(
                child: SizedBox(
                  width: 18,
                  height: 18,
                  child: CircularProgressIndicator(strokeWidth: 2),
                ),
              );
            }
            final renderer = JsonWidgetRenderer(
              theme: JsonWidgetTheme.fromAccent(
                theme.colorScheme.primary,
                brightness: theme.brightness,
              ),
              mapTileProvider: widget.mapTileProvider,
              // 3D scenes render in tiles too (display-only — no tap picking:
              // any tap opens the full app).
              js3dHost: createFaJs3dHost(widget.env),
              // Without a media host the renderer falls back to a placeholder
              // for video/audio nodes — live tiles with media need it too.
              mediaHost: const FaMediaHost(),
              // Display-only tile (default): any UI event opens the full app.
              // An interactive tile (`"widget": {"interactive": true}`) gets
              // its taps routed to the tile engine's jsr.onEvent instead —
              // the app opens via the tile menu (long-press / right-click).
              onEvent: widget.app.tileWidget?.interactive == true
                  ? (actionId, payload) {
                      unawaited(engine.callEvent(actionId, payload));
                    }
                  : (actionId, payload) => widget.onOpen(),
            );
            return ViewportReporter(
              onSize: (size) => engine.dispatchHostEvent('viewport', {
                'width': size.width,
                'height': size.height,
              }),
              child: renderer.build(tree, context),
            );
          },
        );
      },
    );
  }
}

