  Future<JsAppEngine?> ensureEngine(
    DynamicMessageDefinition definition, {
    String? locale,
    Map<String, dynamic>? theme,
    Future<RequestSecretResult?> Function(String name, String reason)?
    keyRequestHandler,
  }) async {
