                    style: Theme.of(
                      context,
                    ).textTheme.titleSmall?.copyWith(color: scheme.error),
                  ),
                ),
                IconButton(
                  tooltip: context.l10n.dynamicTileRetry,
                  icon: const Icon(Icons.refresh, size: 20),
                  onPressed: () => unawaited(
                    widget.service.retryBoot(
